import{z as o,x as s,o as B,c as i,q as A,j as t,D as a,d as e,s as l,S as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"评测前沿收束","description":"","frontmatter":{"title":"评测前沿收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ef-map.md","filePath":"llm/ef-map.md","lastUpdated":1791063341000}'),D={name:"llm/ef-map.md"};function d(p,E,g,m,_,F){const r=s("Mermaid");return B(),i("div",null,[E[2]||(E[2]=A('<h1 id="评测前沿收束" tabindex="-1">评测前沿收束 <a class="header-anchor" href="#评测前沿收束" aria-label="Permalink to &quot;评测前沿收束&quot;">​</a></h1><div class="epigraph"><p>评测的前沿不是更多分数，而是每个分数都能回答三件事：测的什么声明、差多大才作数、谁校准的尺子。</p><footer>—— 据 Zheng 等 2023、Liang 等 HELM 2022、Gao 等 2023 与本课程各课口径，按本课程整理</footer></div><p><a href="/llm/ef-train-eval-synergy">上一课</a>把评测接回训练，双列表与单向通道给协同立了合同。至此零件齐了：法官的深化给开放任务一台可标定的仪器，竞技场方法学给人类偏好一条带区间的名次，维度体系把声明钉到格子，新任务设计把空格变成卷子，功效分析定样本量的资格，私有评测建成分层的机构能力，组合策略管仪器的进出与预算。本课把它们装配成一张决策单和几条不变量。<strong>本课程到此收束。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>九件事散在八处会互相拆台：没有轴就不知道补哪张卷；没有功效就不知道卷子该多大；没有盲库，组合里最好的尺子半年就被训练吃掉；没有归因通道，门禁失败只会变成重跑。收束要回答的是顺序与不变量——哪些选择先行、哪些参数可以换代而骨架不动。<span class="marginnote">为什么顺序本身是内容：先把仪器配齐再算功效，可能发现样本量根本凑不够，设计推倒重来；先攒一堆卷子再立声明，卷子是照别人榜单挑的，跟自家产品对不上。顺序错了不是省事，是把返工推迟到更贵的环节。</span>这与<a href="/llm/aeval-map">对齐评测收束</a>同一层问题，但对象换成了全谱系的评测方法，而不只安全与对齐。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>决策单</strong>，按依赖排序：</p><ol><li><strong>声明与轴</strong>：从产品声明与风险清单倒推维度体系，空格即待办。</li><li><strong>仪器分派</strong>：每个声明配仪器——程序判、标定法官、人评、环境化，异质尺至少各一把。</li><li><strong>卷子设计</strong>：谓词、抽样框、判定器、试点、冻结，六步留档。</li><li><strong>功效账</strong>：定 \\(\\delta\\)、\\(\\alpha\\) 与功效，算出 \\(n\\) 与配对方式，区间是产出的默认形态。</li><li><strong>私有建设</strong>：渠道、三级分层、盲库与治理五条。</li><li><strong>组合分层</strong>：探针 → 烟雾 → 回归 → 门禁 → 外部对表，按功效分配预算，按相关性去冗余。</li><li><strong>训练协同</strong>：双列表与单向审批通道，KL 预算当合同。</li><li><strong>对外对表</strong>：公开卷与竞技场坐标定期校准，分叉记档。</li></ol>',8)),(B(),t(n,null,{default:a(()=>[l(r,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20TD%0A%20%20D1%5B%22%E5%A3%B0%E6%98%8E%E4%B8%8E%E8%BD%B4%22%5D%20--%3E%20D2%5B%22%E4%BB%AA%E5%99%A8%E5%88%86%E6%B4%BE%22%5D%0A%20%20D2%20--%3E%20D3%5B%22%E5%8D%B7%E5%AD%90%E8%AE%BE%E8%AE%A1%E4%B8%8E%E5%86%BB%E7%BB%93%22%5D%0A%20%20D3%20--%3E%20D4%5B%22%E5%8A%9F%E6%95%88%E8%B4%A6%EF%BC%9An%20%E4%B8%8E%E9%85%8D%E5%AF%B9%22%5D%0A%20%20D4%20--%3E%20D5%5B%22%E7%A7%81%E6%9C%89%E5%BB%BA%E8%AE%BE%E4%B8%8E%E7%9B%B2%E5%BA%93%22%5D%0A%20%20D5%20--%3E%20D6%5B%22%E7%BB%84%E5%90%88%E5%88%86%E5%B1%82%E4%B8%8E%E9%A2%84%E7%AE%97%22%5D%0A%20%20D6%20--%3E%20D7%5B%22%E8%AE%AD%E7%BB%83%E5%8D%8F%E5%90%8C%EF%BC%9A%E5%8F%8C%E5%88%97%E4%B8%8E%E9%80%9A%E9%81%93%22%5D%0A%20%20D7%20--%3E%20D8%5B%22%E5%A4%96%E9%83%A8%E5%AF%B9%E8%A1%A8%E4%B8%8E%E5%88%86%E5%8F%89%E8%AE%B0%E6%A1%A3%22%5D%0A%20%20INV%5B%22%E5%9B%9B%E6%9D%A1%E4%B8%8D%E5%8F%98%E9%87%8F%22%5D%20-.-%3E%20D2%0A%20%20INV%20-.-%3E%20D4%0A%20%20INV%20-.-%3E%20D7%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>骨架是四条不变量。<strong>声明先行</strong>：先有可证伪的声明，再选仪器；反过来先有分数再找说法，评测量产出的只是材料。<strong>仪器必标定</strong>：法官对人标定、卷子过试点、人评有协议——没有标定环节的仪器不进主表。<strong>资格线前置</strong>：名次差要在功效账里先取得作数的资格，区间相交不下结论；这条把「进步叙事」挡在统计之外。<strong>指南针与门禁分离</strong>：训练看得见的永远不当发布依据，盲库是组合里最贵也最值得的资产。<span class="marginnote">「指南针」与「门禁」可用开车打比方：指南针是训练时随时瞄的仪表盘，告诉你方向对不对、允许有误差；门禁是上路前必须过的年检，标准严格，而且驾驶员不能提前知道考题。拿训练时盯着的卷子直接当年检，等于自己给自己发驾照。</span>参数会换代——模型、法官、题面、榜全都会——这四条不动；换代的每一步走版本冻结与变更审批，跨版分数不直减。</p>',2)),(B(),t(n,null,{default:a(()=>[l(r,{id:"mermaid-68",class:"mermaid",graph:"flowchart%20TD%0A%20%20F1%5B%22%E7%BF%BB%E8%BD%A6%E4%B8%80%3A%20%E5%85%88%E6%9C%89%E5%88%86%E6%95%B0%3Cbr%2F%3E%E5%86%8D%E6%89%BE%E8%AF%B4%E6%B3%95%22%5D%20--%3E%20G1%5B%22%E5%A3%B0%E6%98%8E%E5%85%88%E8%A1%8C%E6%8B%A6%E4%BD%8F%E5%AE%83%3A%3Cbr%2F%3E%E5%85%88%E5%86%99%E5%8F%AF%E8%AF%81%E4%BC%AA%E7%9A%84%E5%A3%B0%E6%98%8E%22%5D%0A%20%20F2%5B%22%E7%BF%BB%E8%BD%A6%E4%BA%8C%3A%20%E6%B3%95%E5%AE%98%E6%B2%A1%E5%AF%B9%E4%BA%BA%E6%A0%87%E5%AE%9A%22%5D%20--%3E%20G2%5B%22%E4%BB%AA%E5%99%A8%E5%BF%85%E6%A0%87%E5%AE%9A%E6%8B%A6%E4%BD%8F%E5%AE%83%3A%3Cbr%2F%3E%E6%97%A0%E6%A0%87%E5%AE%9A%E4%B8%8D%E8%BF%9B%E4%B8%BB%E8%A1%A8%22%5D%0A%20%20F3%5B%22%E7%BF%BB%E8%BD%A6%E4%B8%89%3A%20%E5%8C%BA%E9%97%B4%E7%9B%B8%E4%BA%A4%3Cbr%2F%3E%E5%B0%B1%E5%96%8A%E8%B6%85%E8%B6%8A%22%5D%20--%3E%20G3%5B%22%E8%B5%84%E6%A0%BC%E7%BA%BF%E5%89%8D%E7%BD%AE%E6%8B%A6%E4%BD%8F%E5%AE%83%3A%3Cbr%2F%3E%E5%8A%9F%E6%95%88%E8%B4%A6%E5%85%88%E5%AE%9A%20n%20%E4%B8%8E%20delta%22%5D%0A%20%20F4%5B%22%E7%BF%BB%E8%BD%A6%E5%9B%9B%3A%20%E8%AE%AD%E7%BB%83%E7%9C%8B%E8%BF%87%E7%9A%84%E5%8D%B7%3Cbr%2F%3E%E7%9B%B4%E6%8E%A5%E5%BD%93%E9%97%A8%E7%A6%81%22%5D%20--%3E%20G4%5B%22%E7%9B%B2%E5%BA%93%E6%8B%A6%E4%BD%8F%E5%AE%83%3A%3Cbr%2F%3E%E6%8C%87%E5%8D%97%E9%92%88%E4%B8%8E%E9%97%A8%E7%A6%81%E5%88%86%E7%A6%BB%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p><span class="marginnote">若只做三件事：给每个对外声明绑一把标定过的仪器；给每个名次配区间并预先声明 \\(\\delta\\)；把发布门禁放进训练组不可读的盲库。本课程见过的大多数评测翻车，在这三步就被拦住。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>这张地图有保鲜期：法官会换代、竞技场会被瞄准、轴会扩容（智能体与多模态都在涌入）、公开卷会背题——所以每张表带版本与日期，过期不续命。<span class="marginnote">为什么每张表要带版本与日期：评测结论是条件句——「在当时的题、当时的法官、当时的对手池下」才成立。半年后法官换了、公开卷被背题了，旧分数就不能直接拿来比新模型。不带版本的分数如同没有生产日期的食品：不是一定坏了，是你没法知道它还能不能吃。</span>地图之外留两翼：评测怎么进报告与披露，<a href="/llm/aeval-reporting-standard">报告规范</a>接棒；评测之后模型怎么改，训练各课接棒。收束的口径是：评测工程交付的始终是同一件事——把「感觉更强」换成「在声明的构念上，差距的区间与标定来源可被任何人审计」。分数有资格说话的时候，评测才谈得上工程。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>决策单八步，依赖排序：声明与轴 → 仪器 → 卷子 → 功效 → 私有 → 组合 → 协同 → 对表。</li><li>四条不变量：声明先行、仪器必标定、资格线前置、指南针与门禁分离。</li><li>异质尺至少各一把；组合按功效分配预算，按相关性去冗余。</li><li>版本冻结跨所有参数换代；跨版分数不直减，分叉记档。</li><li>出处：Zheng 等 2023；Liang 等 HELM 2022；Gao 等 2023；Bradley 与 Terry 1952、Dubois 等 2024 与本课程各课口径，按本课程整理。</li></ul>',5))])}const C=o(D,[["render",d]]);export{f as __pageData,C as default};
